1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	
60		// silences keyed by silence id; same lock so alert evaluation reads
61		// metrics, rules and silences from one consistent snapshot.
62		silences map[string]*silence
63	
64		// inhibit rules keyed by rule id; same lock so alert evaluation also
65		// reads inhibit rules from the same consistent snapshot.
66		inhibitions map[string]*inhibitRule
67	}
68	
69	func newMetricStore() *metricStore {
70		return &metricStore{
71			series:      make(map[string]*series),
72			rules:       make(map[string]*alertRule),
73			silences:    make(map[string]*silence),
74			inhibitions: make(map[string]*inhibitRule),
75		}
76	}
77	
78	// validatedSample is a sample that passed all format and value checks.
79	type validatedSample struct {
80		key     string
81		name    string
82		typ     string
83		labels  map[string]string
84		value   float64
85		buckets []float64 // non-nil for histograms
86	}
87	
88	// checkAndApply validates the batch against the current state (and against
89	// itself) and then commits it in array order. A false result signals a type or
90	// bucket-boundary conflict; in that case no state is mutated.
91	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
92		s.mu.Lock()
93		defer s.mu.Unlock()
94	
95		// First pass: conflict detection against committed state and earlier
96		// samples in the same batch.
97		resolved := make(map[string]*series, len(batch))
98		for _, sm := range batch {
99			existing, ok := s.series[sm.key]
100			if !ok {
101				if shadow, seen := resolved[sm.key]; seen {
102					existing, ok = shadow, true
103				}
104			}
105			if ok {
106				if existing.typ != sm.typ {
107					return false
108				}
109				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
110					return false
111				}
112				resolved[sm.key] = existing
113				continue
114			}
115			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
116		}
117	
118		// Second pass: commit in order.
119		for _, sm := range batch {
120			cur, ok := s.series[sm.key]
121			if !ok {
122				cur = &series{
123					name:         sm.name,
124					typ:          sm.typ,
125					labels:       sm.labels,
126					bucketBounds: append([]float64(nil), sm.buckets...),
127				}
128				if sm.typ == "histogram" {
129					cur.bucketCounts = make([]int64, len(sm.buckets))
130				}
131				s.series[sm.key] = cur
132			}
133			switch sm.typ {
134			case "counter":
135				cur.value += sm.value
136			case "gauge":
137				cur.value = sm.value
138			case "histogram":
139				cur.count++
140				cur.sum += sm.value
141				for i, bound := range cur.bucketBounds {
142					if sm.value <= bound {
143						cur.bucketCounts[i]++
144					}
145				}
146			}
147		}
148		return true
149	}
150	
151	type seriesOutput struct {
152		Name    string            `json:"name"`
153		Type    string            `json:"type"`
154		Labels  map[string]string `json:"labels"`
155		Value   *float64          `json:"value,omitempty"`
156		Count   *int64            `json:"count,omitempty"`
157		Sum     *float64          `json:"sum,omitempty"`
158		Buckets []bucketOutput    `json:"buckets,omitempty"`
159	}
160	
161	type bucketOutput struct {
162		LE    float64 `json:"le"`
163		Count int64   `json:"count"`
164	}
165	
166	// query returns matching series as ready-to-encode outputs. A series matches
167	// when its name equals name exactly and it contains every selector label.
168	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
169		s.mu.RLock()
170		defer s.mu.RUnlock()
171	
172		out := make([]seriesOutput, 0)
173		for _, cur := range s.series {
174			if cur.name != name {
175				continue
176			}
177			matched := true
178			for k, v := range selector {
179				got, ok := cur.labels[k]
180				if !ok || got != v {
181					matched = false
182					break
183				}
184			}
185			if !matched {
186				continue
187			}
188			item := seriesOutput{
189				Name:   cur.name,
190				Type:   cur.typ,
191				Labels: copyLabels(cur.labels),
192			}
193			switch cur.typ {
194			case "counter", "gauge":
195				v := cur.value
196				item.Value = &v
197			case "histogram":
198				c, sum := cur.count, cur.sum
199				item.Count = &c
200				item.Sum = &sum
201				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
202				for i, bound := range cur.bucketBounds {
203					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
204				}
205			}
206			out = append(out, item)
207		}
208	
209		sort.Slice(out, func(i, j int) bool {
210			return compareLabels(out[i].Labels, out[j].Labels) < 0
211		})
212		return out
213	}
214	
215	// compareLabels imposes a normalized lexicographic order on full label sets:
216	// keys are sorted, then (key, value) pairs are compared element-wise, and a
217	// shorter pair list sorts first when it is a prefix of a longer one.
218	func compareLabels(a, b map[string]string) int {
219		ka := sortedKeys(a)
220		kb := sortedKeys(b)
221		n := len(ka)
222		if len(kb) < n {
223			n = len(kb)
224		}
225		for i := 0; i < n; i++ {
226			if ka[i] != kb[i] {
227				return strings.Compare(ka[i], kb[i])
228			}
229			if a[ka[i]] != b[kb[i]] {
230				return strings.Compare(a[ka[i]], b[kb[i]])
231			}
232		}
233		switch {
234		case len(ka) < len(kb):
235			return -1
236		case len(ka) > len(kb):
237			return 1
238		default:
239			return 0
240		}
241	}
242	
243	func sortedKeys(m map[string]string) []string {
244		keys := make([]string, 0, len(m))
245		for k := range m {
246			keys = append(keys, k)
247		}
248		sort.Strings(keys)
249		return keys
250	}
251	
252	func copyLabels(in map[string]string) map[string]string {
253		out := make(map[string]string, len(in))
254		for k, v := range in {
255			out[k] = v
256		}
257		return out
258	}
259	
260	// seriesKey builds a collision-free identity from name + unordered labels.
261	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
262	// so length-prefixed values remove any ambiguity from arbitrary label values.
263	func seriesKey(name string, labels map[string]string) string {
264		var b strings.Builder
265		b.WriteString(name)
266		for _, k := range sortedKeys(labels) {
267			b.WriteByte(0)
268			b.WriteString(k)
269			b.WriteByte(0)
270			v := labels[k]
271			b.WriteString(strconv.Itoa(len(v)))
272			b.WriteByte(0)
273			b.WriteString(v)
274		}
275		return b.String()
276	}
277	
278	func equalBuckets(a, b []float64) bool {
279		if len(a) != len(b) {
280			return false
281		}
282		for i := range a {
283			if a[i] != b[i] {
284				return false
285			}
286		}
287		return true
288	}
289	
290	// Handler returns the HTTP surface served by SignalWatch.
291	func Handler() http.Handler {
292		mux := http.NewServeMux()
293		store := newMetricStore()
294	
295		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
296			if r.Method != http.MethodGet {
297				w.Header().Set("Allow", http.MethodGet)
298				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
299				return
300			}
301			w.Header().Set("Content-Type", "application/json; charset=utf-8")
302			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
303		})
304	
305		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
306			switch r.Method {
307			case http.MethodGet:
308				handleMetricsGet(w, r, store)
309			case http.MethodPost:
310				handleMetricsPost(w, r, store)
311			default:
312				w.Header().Set("Allow", "GET, POST")
313				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
314			}
315		})
316	
317		registerAlertHandlers(mux, store)
318		registerSilenceHandlers(mux, store)
319		registerInhibitHandlers(mux, store)
320	
321		return mux
322	}
323	
324	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
325		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
326		if err != nil || mediaType != "application/json" {
327			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
328			return
329		}
330	
331		body, err := io.ReadAll(r.Body)
332		if err != nil {
333			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
334			return
335		}
336	
337		batch, ok := decodeMetricsBatch(body)
338		if !ok {
339			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
340			return
341		}
342	
343		if !store.checkAndApply(batch) {
344			writeAPIError(w, "metric_conflict", http.StatusConflict)
345			return
346		}
347	
348		w.Header().Set("Content-Type", "application/json; charset=utf-8")
349		w.WriteHeader(http.StatusAccepted)
350		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
351	}
352	
353	type metricsEnvelope struct {
354		Samples *[]json.RawMessage `json:"samples"`
355	}
356	
357	type rawSample struct {
358		Name    *string            `json:"name"`
359		Type    *string            `json:"type"`
360		Labels  *map[string]string `json:"labels"`
361		Value   *float64           `json:"value"`
362		Buckets *[]float64         `json:"buckets"`
363	}
364	
365	// decodeMetricsBatch performs every format and value check. It never returns a
366	// partially validated batch.
367	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
368		var env metricsEnvelope
369		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
370			return nil, false
371		}
372	
373		batch := make([]validatedSample, 0, len(*env.Samples))
374		for _, raw := range *env.Samples {
375			var sm rawSample
376			if !strictDecode(raw, &sm) {
377				return nil, false
378			}
379			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
380				return nil, false
381			}
382			name, typ := *sm.Name, *sm.Type
383			if !identPattern.MatchString(name) {
384				return nil, false
385			}
386			if typ != "counter" && typ != "gauge" && typ != "histogram" {
387				return nil, false
388			}
389			labels := *sm.Labels
390			if labels == nil {
391				return nil, false // explicit null labels
392			}
393			for k := range labels {
394				if !identPattern.MatchString(k) {
395					return nil, false
396				}
397			}
398			value := *sm.Value
399			if math.IsNaN(value) || math.IsInf(value, 0) {
400				return nil, false // encoding/json already rejects NaN/Inf tokens
401			}
402			if typ == "counter" && value < 0 {
403				return nil, false
404			}
405	
406			var buckets []float64
407			if typ == "histogram" {
408				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
409					return nil, false
410				}
411				buckets = append([]float64(nil), (*sm.Buckets)...)
412			} else if sm.Buckets != nil {
413				return nil, false // buckets only valid on histograms
414			}
415	
416			batch = append(batch, validatedSample{
417				key:     seriesKey(name, labels),
418				name:    name,
419				typ:     typ,
420				labels:  copyLabels(labels),
421				value:   value,
422				buckets: buckets,
423			})
424		}
425		return batch, true
426	}
427	
428	func validBuckets(buckets []float64) bool {
429		if len(buckets) == 0 {
430			return false
431		}
432		prev := math.Inf(-1)
433		for _, b := range buckets {
434			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
435				return false
436			}
437			prev = b
438		}
439		return true
440	}
441	
442	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
443	// values and non-object payloads for struct targets.
444	func strictDecode(data []byte, target any) bool {
445		dec := json.NewDecoder(bytes.NewReader(data))
446		dec.DisallowUnknownFields()
447		if err := dec.Decode(target); err != nil {
448			return false
449		}
450		var extra json.RawMessage
451		if err := dec.Decode(&extra); err != io.EOF {
452			return false
453		}
454		return true
455	}
456	
457	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
458		values, err := url.ParseQuery(r.URL.RawQuery)
459		if err != nil {
460			writeAPIError(w, "invalid_query", http.StatusBadRequest)
461			return
462		}
463	
464		names := values["name"]
465		if len(names) == 0 || !identPattern.MatchString(names[0]) {
466			writeAPIError(w, "invalid_query", http.StatusBadRequest)
467			return
468		}
469	
470		selector := make(map[string]string)
471		for key, vals := range values {
472			if !strings.HasPrefix(key, "label.") {
473				continue
474			}
475			labelKey := strings.TrimPrefix(key, "label.")
476			if !identPattern.MatchString(labelKey) {
477				writeAPIError(w, "invalid_query", http.StatusBadRequest)
478				return
479			}
480			for _, v := range vals[1:] {
481				if v != vals[0] {
482					writeAPIError(w, "invalid_query", http.StatusBadRequest)
483					return
484				}
485			}
486			selector[labelKey] = vals[0]
487		}
488	
489		seriesList := store.query(names[0], selector)
490		w.Header().Set("Content-Type", "application/json; charset=utf-8")
491		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
492	}
493	
494	func writeAPIError(w http.ResponseWriter, code string, status int) {
495		w.Header().Set("Content-Type", "application/json; charset=utf-8")
496		w.WriteHeader(status)
497		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
498	}
499

