268	// evalAlerts computes every rule against a single consistent snapshot of
269	// metrics, rules, silences and inhibit rules; results are sorted by rule id.
270	// Original state, value and silencing are evaluated first; inhibition is then
271	// applied to the original firing states so silenced or inhibited alerts still
272	// act as inhibition sources.
273	func (s *metricStore) evalAlerts() []alertOutput {
274		s.mu.RLock()
275		defer s.mu.RUnlock()
276	
277		rules := make([]*alertRule, 0, len(s.rules))
278		for _, r := range s.rules {
279			rules = append(rules, r)
280		}
281		sort.Slice(rules, func(i, j int) bool { return rules[i].id < rules[j].id })
282	
283		silences := make([]*silence, 0, len(s.silences))
284		for _, sil := range s.silences {
285			silences = append(silences, sil)
286		}
287		inhibitRules := make([]*inhibitRule, 0, len(s.inhibitions))
288		for _, ir := range s.inhibitions {
289			inhibitRules = append(inhibitRules, ir)
290		}
291		// Evaluation instant and silence windowing share the snapshot.
292		now := time.Now()
293		activeByRule := activeSilencesByRule(silences, now)
294	
295		out := make([]alertOutput, 0, len(rules))
296		for _, r := range rules {
297			al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}, InhibitionIDs: []string{}}
298	
299			var value float64
300			if r.kind == "threshold" {
301				sum, ok := s.selectorSum(r.left)
302				if !ok {
303					al.State = "no_data"
304					out = append(out, al)
305					continue
306				}
307				value = sum
308			} else {
309				num, numOK := s.selectorSum(r.left)
310				den, denOK := s.selectorSum(r.right)
311				if !numOK || !denOK || den == 0 {
312					al.State = "no_data"
313					out = append(out, al)
314					continue
315				}
316				value = num / den
317			}
318	
319			v := value
320			al.Value = &v
321			if compareHolds(r.operator, value, r.threshold) {
322				al.State = "firing"
323				if hits := activeByRule[r.id]; len(hits) > 0 {
324					al.Silenced = true
325					al.SilenceIDs = append([]string(nil), hits...)
326				}
327			}
328			out = append(out, al)
329		}
330	
331		applyInhibitions(out, inhibitRules)
332		return out
333	}
