335	// applyInhibitions annotates alerts with the inhibit rules that hit them. A
336	// rule hits an alert when the alert's original state is firing and at least
337	// one existing source alert's original state is firing. Sources fire
338	// regardless of their own silenced/inhibited flags, and the target's state,
339	// value and silencing are left untouched.
340	func applyInhibitions(alerts []alertOutput, inhibitRules []*inhibitRule) {
341		firing := make(map[string]bool, len(alerts))
342		for i := range alerts {
343			if alerts[i].State == "firing" {
344				firing[alerts[i].ID] = true
345			}
346		}
347	
348		for i := range alerts {
349			if alerts[i].State != "firing" {
350				continue
351			}
352			var hits []string
353			for _, ir := range inhibitRules {
354				if !containsString(ir.targetRuleIDs, alerts[i].ID) {
355					continue
356				}
357				for _, sourceID := range ir.sourceRuleIDs {
358					if firing[sourceID] {
359						hits = append(hits, ir.id)
360						break
361					}
362				}
363			}
364			if len(hits) > 0 {
365				sort.Strings(hits)
366				alerts[i].Inhibited = true
367				alerts[i].InhibitionIDs = hits
368			}
369		}
370	}
