372	func containsString(list []string, want string) bool {
373		for _, v := range list {
374			if v == want {
375				return true
376			}
377		}
378		return false
379	}
380	
381	func compareHolds(operator string, value, threshold float64) bool {
382		switch operator {
383		case "gt":
384			return value > threshold
385		case "gte":
386			return value >= threshold
387		case "lt":
388			return value < threshold
389		case "lte":
390			return value <= threshold
391		}
392		return false
393	}
