413			id := strings.TrimPrefix(r.URL.Path, alertRulesPrefix)
414			switch r.Method {
415			case http.MethodGet, http.MethodDelete:
416				// Reads and deletions can only address an existing, syntactically
417				// valid rule id; anything else is simply not found.
418				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
419					writeAPIError(w, "rule_not_found", http.StatusNotFound)
