429				// an identifier-shaped but invalid id is a bad rule identifier.
430				if id == "" || strings.Contains(id, "/") {
431					writeAPIError(w, "rule_not_found", http.StatusNotFound)
432					return
433				}
434				if !identPattern.MatchString(id) {
435					writeAPIError(w, "invalid_rule", http.StatusBadRequest)
436					return
437				}
438				handleRulePut(w, r, id, store)
439			default:
440				w.Header().Set("Allow", "GET, PUT, DELETE")
441				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
442			}
443		})
444	
445		mux.HandleFunc(alertsPath, func(w http.ResponseWriter, r *http.Request) {
446			if r.Method != http.MethodGet {
447				w.Header().Set("Allow", http.MethodGet)
448				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
449				return
450			}
451			writeJSON(w, http.StatusOK, map[string]any{"alerts": store.evalAlerts()})
452		})
