1	package server
2	
3	import (
4		"io"
5		"mime"
6		"net/http"
7		"sort"
8		"strings"
9		"time"
10	)
11	
12	const (
13		silencesPath   = "/api/v1/silences"
14		silencesPrefix = silencesPath + "/"
15	)
16	
17	// silence is an immutable silence document. Replacements swap the pointer
18	// atomically, so readers never observe a half-updated silence.
19	type silence struct {
20		id       string
21		ruleIDs  []string
22		startsAt time.Time
23		endsAt   time.Time
24		comment  string
25	
26		// raw timestamps are echoed verbatim so GET returns exactly what was PUT.
27		startsAtRaw string
28		endsAtRaw   string
29	}
30	
31	// stateAt classifies the silence relative to the given evaluation instant.
32	func (s *silence) stateAt(now time.Time) string {
33		switch {
34		case now.Before(s.startsAt):
35			return "upcoming"
36		case now.Before(s.endsAt):
37			return "active"
38		default:
39			return "expired"
40		}
41	}
42	
43	// activeAt reports whether the silence covers now, i.e.
44	// starts_at <= now < ends_at.
45	func (s *silence) activeAt(now time.Time) bool {
46		return !now.Before(s.startsAt) && now.Before(s.endsAt)
47	}
48	
49	// ---- JSON wire shapes ------------------------------------------------------
50	
51	type silenceJSON struct {
52		ID       string   `json:"id"`
53		RuleIDs  []string `json:"rule_ids"`
54		StartsAt string   `json:"starts_at"`
55		EndsAt   string   `json:"ends_at"`
56		Comment  string   `json:"comment"`
57		State    string   `json:"state"`
58	}
59	
60	func silenceWireJSON(s *silence, now time.Time) silenceJSON {
61		return silenceJSON{
62			ID:       s.id,
63			RuleIDs:  append([]string(nil), s.ruleIDs...),
64			StartsAt: s.startsAtRaw,
65			EndsAt:   s.endsAtRaw,
66			Comment:  s.comment,
67			State:    s.stateAt(now),
68		}
69	}
70	
71	// ---- request decoding ------------------------------------------------------
72	
73	type rawSilence struct {
74		RuleIDs  *[]string `json:"rule_ids"`
75		StartsAt *string   `json:"starts_at"`
76		EndsAt   *string   `json:"ends_at"`
77		Comment  *string   `json:"comment"`
78	}
79	
80	// decodeSilence parses and fully validates a silence body. It never returns a
81	// partially validated silence.
82	func decodeSilence(body []byte) (*silence, bool) {
83		var raw rawSilence
84		if !strictDecode(body, &raw) {
85			return nil, false
86		}
87		if raw.RuleIDs == nil || raw.StartsAt == nil || raw.EndsAt == nil || raw.Comment == nil {
88			return nil, false
89		}
90	
91		ruleIDs := *raw.RuleIDs
92		if len(ruleIDs) == 0 {
93			return nil, false
94		}
95		seen := make(map[string]bool, len(ruleIDs))
96		for _, id := range ruleIDs {
97			if !identPattern.MatchString(id) || seen[id] {
98				return nil, false
99			}
100			seen[id] = true
101		}
102	
103		startsAt, err := time.Parse(time.RFC3339, *raw.StartsAt)
104		if err != nil {
105			return nil, false
106		}
107		endsAt, err := time.Parse(time.RFC3339, *raw.EndsAt)
108		if err != nil {
109			return nil, false
110		}
111		if !startsAt.Before(endsAt) {
112			return nil, false
113		}
114	
115		return &silence{
116			ruleIDs:     append([]string(nil), ruleIDs...),
117			startsAt:    startsAt,
118			endsAt:      endsAt,
119			comment:     *raw.Comment,
120			startsAtRaw: *raw.StartsAt,
121			endsAtRaw:   *raw.EndsAt,
122		}, true
123	}
124	
125	// ---- store operations ------------------------------------------------------
126	
127	func (s *metricStore) putSilence(sil *silence) bool {
128		s.mu.Lock()
129		defer s.mu.Unlock()
130		_, existed := s.silences[sil.id]
131		s.silences[sil.id] = sil
132		return !existed
133	}
134	
135	func (s *metricStore) getSilence(id string) (*silence, bool) {
136		s.mu.RLock()
137		defer s.mu.RUnlock()
138		sil, ok := s.silences[id]
139		return sil, ok
140	}
141	
142	func (s *metricStore) deleteSilence(id string) bool {
143		s.mu.Lock()
144		defer s.mu.Unlock()
145		if _, ok := s.silences[id]; !ok {
146			return false
147		}
148		delete(s.silences, id)
149		return true
150	}
151	
152	// snapshotSilences returns all silences sorted by id. Silence objects are
153	// immutable, so the pointers stay safe after the lock is released.
154	func (s *metricStore) snapshotSilences() []*silence {
155		s.mu.RLock()
156		defer s.mu.RUnlock()
157		out := make([]*silence, 0, len(s.silences))
158		for _, sil := range s.silences {
159			out = append(out, sil)
160		}
161		sort.Slice(out, func(i, j int) bool { return out[i].id < out[j].id })
162		return out
163	}
164	
165	// ---- HTTP handlers ---------------------------------------------------------
166	
167	func registerSilenceHandlers(mux *http.ServeMux, store *metricStore) {
168		mux.HandleFunc(silencesPath, func(w http.ResponseWriter, r *http.Request) {
169			if r.Method != http.MethodGet {
170				w.Header().Set("Allow", http.MethodGet)
171				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
172				return
173			}
174			now := time.Now()
175			silences := store.snapshotSilences()
176			body := make([]silenceJSON, 0, len(silences))
177			for _, sil := range silences {
178				body = append(body, silenceWireJSON(sil, now))
179			}
180			writeJSON(w, http.StatusOK, map[string]any{"silences": body})
181		})
182	
183		mux.HandleFunc(silencesPrefix, func(w http.ResponseWriter, r *http.Request) {
184			id := strings.TrimPrefix(r.URL.Path, silencesPrefix)
185			switch r.Method {
186			case http.MethodGet, http.MethodDelete:
187				// Reads and deletions can only address an existing, syntactically
188				// valid silence id; anything else is simply not found.
189				if id == "" || strings.Contains(id, "/") || !identPattern.MatchString(id) {
190					writeAPIError(w, "silence_not_found", http.StatusNotFound)
191					return
192				}
193				if r.Method == http.MethodGet {
194					handleSilenceGet(w, id, store)
195				} else {
196					handleSilenceDelete(w, id, store)
197				}
198			case http.MethodPut:
199				// A structurally nested path is outside this resource subtree;
200				// an identifier-shaped but invalid id is a bad identifier.
201				if id == "" || strings.Contains(id, "/") {
202					writeAPIError(w, "silence_not_found", http.StatusNotFound)
