func routeRequest(t *testing.T, h http.Handler, method, id, body, contentType string) *httptest.ResponseRecorder {
	t.Helper()
	target := notificationRoutesPath
	if id != "" {
		target += "/" + id
	}
	rec := httptest.NewRecorder()
