	if len(deliveries) != 2 {
		t.Fatalf("deliveries = %v", deliveries)
	}
	d0 := deliveries[0].(map[string]any)
	d1 := deliveries[1].(map[string]any)
	if d0["alert_id"] != "a_fire" || d0["receiver"] != "team_high" || d0["route_id"] != "r_high" {
		t.Fatalf("delivery[0] = %v", d0)
	}
